head.script:

	scwin.onpageload = function() {
		inputCalendar1.setHoliday("20220323 20220324")

		inputCalendar1.disableDate("*")


	};

	scwin.setVal1 = function() {
		inputCalendar1_calendar.gotoCalendar('20220323', {noSelectable : true});
	}

	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_img').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setVal1()");
		WebSquare.wUnit.addCommand("pause", "800");		
		WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#inputCalendar1_calendar_cell_3_4').hasClass('w2calendar_holiday')", "false");
		WebSquare.wUnit.addCommand("pause", "300");
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
    scwin.unitTest();

	scwin.onpageunload = function() {

	};
